import {
  announce,
  createChange,
  css,
  definePrimitive,
  dispatch,
  prepareAnnouncements,
  type ChangeDetails,
} from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"
import {
  clampBox,
  clampFraction as clamp,
  mapRegionBox,
  type ImageScanBox,
  type ImageScanFit,
  type ImageScanSize,
} from "@/lib/image-scan-geometry"
import { isElementOf } from "@/lib/narrow"

type ImageScanStatus = "uploaded" | "scanning" | "result" | "error"

type ImageScanRegionItem = { value: string; label: string }

/** Why a region was selected: a press on its box or its legend row, or a call (an agent, a controller). */
type ImageScanSelectReason = "item-press" | "imperative"

type ImageScanActionReason = "trigger-press" | "imperative"

type ImageScanAnnouncements = {
  scanning: string
  /** `percent` is a whole number from 0 to 100. */
  progress: (percent: number) => string
  result: (count: number) => string
  error: string
}

type ImageScanOptions = {
  status?: ImageScanStatus
  /** From 0 to 1; undefined while the scan can't tell how far it is. */
  progress?: number
  regions?: readonly ImageScanRegionItem[]
  selectedRegion?: string | null
  defaultSelectedRegion?: string | null
  onSelectedRegionChange?: (region: string | null, details: ChangeDetails<ImageScanSelectReason>) => void
  onCancel?: (value: null, details: ChangeDetails<ImageScanActionReason>) => void
  onRetry?: (value: null, details: ChangeDetails<ImageScanActionReason>) => void
  onScan?: (value: null, details: ChangeDetails<ImageScanActionReason>) => void
  /** The image's width over its height, when known before it loads. */
  ratio?: number
  /** The frame's width over its height; the image's own ratio by default. */
  aspectRatio?: number
  fit?: ImageScanFit
  announcements?: ImageScanAnnouncements
}

const percentOf = (value: number) => `${String(Math.round(value * 10_000) / 100)}%`

// Progress is read at most every tenth, and no sooner than this after the last reading, so a screen reader isn't
// talked over by a fast scan.
const progressStep = 10
const progressInterval = 2000

// A box this close to the top has no room for its label above it, so the label sits inside.
const topEdge = 0.12

const defaultRatio = 4 / 3

const whenWords: Record<ImageScanStatus, string> = {
  uploaded: "before a scan",
  scanning: "while scanning",
  result: "in the result",
  error: "after an error",
}

const imageScan = definePrimitive({
  name: "image-scan",
  options: {
    status: "string",
    progress: "number",
    regions: "value",
    selectedRegion: "value",
    defaultSelectedRegion: "value",
    onSelectedRegionChange: "callback",
    onCancel: "callback",
    onRetry: "callback",
    onScan: "callback",
    ratio: "number",
    aspectRatio: "number",
    fit: "string",
    announcements: "value",
  },
  controlled: ["selectedRegion", "status"],
  state: (options: ImageScanOptions) => ({
    status: options.status ?? "uploaded",
    progress: options.progress,
    regions: options.regions ?? [],
    selectedRegion: options.selectedRegion ?? options.defaultSelectedRegion ?? null,
    highlighted: null as string | null,
    measuredRatio: undefined as number | undefined,
    ratio: options.ratio,
    aspectRatio: options.aspectRatio,
    fit: options.fit ?? "contain",
  }),
  sync: (options) => ({
    status: options.status ?? "uploaded",
    progress: options.progress,
    regions: options.regions ?? [],
    ratio: options.ratio,
    aspectRatio: options.aspectRatio,
    fit: options.fit ?? "contain",
    ...(options.selectedRegion === undefined ? {} : { selectedRegion: options.selectedRegion }),
  }),
  api: (context) => {
    const change = createChange(context)
    const run = (name: "onCancel" | "onRetry" | "onScan", when: ImageScanStatus, event?: Event) => {
      const action = name.slice(2).toLowerCase()
      const call = { reason: event ? "trigger-press" : "imperative", event } as const
      const { status } = context.store.get()
      if (status !== when) return unavailable(action, `works only ${whenWords[when]} (status: ${status})`, call)
      if (!context.options()[name]) return unavailable(action, `isn't offered: there is no ${name}`, call)
      return settled(!dispatch(context, name, null, call), action, call)
    }
    const api = {
      /** Stops a running scan through `onCancel`. */
      cancel: (event?: Event) => run("onCancel", "scanning", event),
      /** Starts again after an error through `onRetry`. */
      retry: (event?: Event) => run("onRetry", "error", event),
      /** Starts a scan of the uploaded image through `onScan`. */
      scan: (event?: Event) => run("onScan", "uploaded", event),
      /** Selects a detected region by its id or label; `null` clears the selection. */
      selectRegion(region: string | null, event?: Event) {
        const { regions, status } = context.store.get()
        const call = { reason: event ? "item-press" : "imperative", event } as const
        if (status !== "result")
          return unavailable("selectRegion", `works only in the result (status: ${status})`, call)
        const match =
          region === null ? null : regions.find((item) => item.value === region || item.label === region)?.value
        if (match === undefined) {
          const names = regions.map((item) => item.label).join(", ")
          throw new Error(`No region "${region ?? ""}". Its regions: ${names || "none"}.`)
        }
        return settled(change("selectedRegion", match, call), "selectRegion", call)
      },
      /** A second press on the selected region clears the selection. */
      toggleRegion(region: string, event?: Event) {
        return api.selectRegion(context.store.get().selectedRegion === region ? null : region, event)
      },
      highlight(region: string | null) {
        if (context.store.get().highlighted !== region) context.store.set({ highlighted: region })
      },
      announcements: () => context.options().announcements,
      regionItems: () => context.store.get().regions.map(({ value, label }) => ({ value, label })),
      measured(ratio: number) {
        if (Number.isFinite(ratio) && ratio > 0) context.store.set({ measuredRatio: ratio })
      },
    }
    return api
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => {
        const ratio = state.ratio ?? state.measuredRatio ?? state.aspectRatio ?? defaultRatio
        return {
          "data-status": state.status,
          "data-fit": state.fit,
          "aria-busy": state.status === "scanning" ? "true" : undefined,
          style: css({
            "--image-scan-ratio": String(ratio),
            "--image-scan-frame-ratio": String(state.aspectRatio ?? ratio),
            "--image-scan-progress": state.progress === undefined ? undefined : String(clamp(state.progress)),
          }),
        }
      },
      bind: (el, part) => {
        const doc = el.ownerDocument
        prepareAnnouncements(doc)
        let { status } = part.store.get()
        let lastStep = -1
        let lastTime = -Infinity
        return part.store.subscribe(() => {
          const state = part.store.get()
          const messages = part.api.announcements()
          if (state.status !== status) {
            status = state.status
            lastStep = -1
            lastTime = -Infinity
            if (!messages) return
            if (status === "scanning") announce(messages.scanning, { doc })
            else if (status === "result") announce(messages.result(state.regions.length), { doc })
            else if (status === "error") announce(messages.error, { doc, priority: "assertive" })
            return
          }
          if (status !== "scanning" || state.progress === undefined || !messages) return
          const percent = Math.round(clamp(state.progress) * 100)
          const step = Math.floor(percent / progressStep)
          const now = Date.now()
          if (step === lastStep || (now - lastTime < progressInterval && percent < 100)) return
          lastStep = step
          lastTime = now
          announce(messages.progress(percent), { doc })
        })
      },
    }),
    frame: slot({
      attrs: (state) => ({ "data-status": state.status }),
    }),
    image: slot({
      attrs: (state) => ({ "data-fit": state.fit, "data-status": state.status }),
      bind: (el, part) => {
        if (!isElementOf(el, "HTMLImageElement")) return
        const image = el
        const read = () => {
          if (image.naturalWidth > 0 && image.naturalHeight > 0)
            part.api.measured(image.naturalWidth / image.naturalHeight)
        }
        read()
        image.addEventListener("load", read)
        return () => image.removeEventListener("load", read)
      },
    }),
    layer: slot({
      attrs: (state) => ({ "data-fit": state.fit, "data-status": state.status }),
    }),
    effect: slot({
      present: (state) => state.status === "scanning",
      attrs: (state) => ({
        "aria-hidden": "true",
        "data-determinate": state.progress === undefined ? undefined : "",
      }),
    }),
    regions: slot<{ label?: string }>({
      props: { label: "string" },
      present: (state) => state.status === "result" && state.regions.length > 0,
      attrs: (_state, part) => ({ "aria-label": part.props.label }),
    }),
    region: slot<{ value: string; box: ImageScanBox; tone?: string; index?: number }>({
      props: { value: "string", box: "value", tone: "string", index: "number" },
      role: "button",
      focus: "native",
      press: ({ api, key }, event) => api.toggleRegion(key, event),
      attrs: (state, part) => {
        const box = clampBox(part.props.box)
        return {
          type: "button",
          "aria-pressed": String(state.selectedRegion === part.key),
          "data-selected": state.selectedRegion === part.key ? "" : undefined,
          "data-highlighted": state.highlighted === part.key ? "" : undefined,
          "data-tone": part.props.tone,
          "data-edge": box.y < topEdge ? "top" : undefined,
          "data-align": box.x > 0.4 && box.x + box.width > 0.6 ? "end" : undefined,
          style: css({
            left: percentOf(box.x),
            top: percentOf(box.y),
            width: percentOf(box.width),
            height: percentOf(box.height),
            "--image-scan-region-index": String(part.props.index ?? 0),
          }),
        }
      },
      on: {
        pointerenter: (_event, { api, key }) => api.highlight(key),
        pointerleave: (_event, { api }) => api.highlight(null),
        focus: (_event, { api, key }) => api.highlight(key),
        blur: (_event, { api }) => api.highlight(null),
      },
    }),
    legend: slot({
      present: (state) => state.status === "result" && state.regions.length > 0,
      attrs: () => ({ "aria-hidden": "true" }),
    }),
    "legend-item": slot<{ value: string; tone?: string }>({
      props: { value: "string", tone: "string" },
      attrs: (state, part) => ({
        "data-selected": state.selectedRegion === part.key ? "" : undefined,
        "data-highlighted": state.highlighted === part.key ? "" : undefined,
        "data-tone": part.props.tone,
      }),
      on: {
        pointerenter: (_event, { api, key }) => api.highlight(key),
        pointerleave: (_event, { api }) => api.highlight(null),
        click: (event, { api, key }) => api.toggleRegion(key, event),
      },
    }),
  }),
  agent: { actions: ["cancel", "retry", "scan", "selectRegion"], items: (api) => api.regionItems() },
})

export { clampBox, imageScan, mapRegionBox }
export type {
  ImageScanActionReason,
  ImageScanAnnouncements,
  ImageScanBox,
  ImageScanFit,
  ImageScanOptions,
  ImageScanRegionItem,
  ImageScanSelectReason,
  ImageScanSize,
  ImageScanStatus,
}

type ImageScanFit = "contain" | "cover"

/** A rectangle on the image, each value a fraction of its width or height, from its top left corner. */
type ImageScanBox = { x: number; y: number; width: number; height: number }

type ImageScanSize = { width: number; height: number }

/**
 * Where a region's box lands in the frame, in the frame's pixels, for an image drawn with `object-fit` and a centred
 * `object-position`. With `cover` the result can reach past the frame, which clips it.
 */
function mapRegionBox(
  box: ImageScanBox,
  { fit, image, frame }: { fit: ImageScanFit; image: ImageScanSize; frame: ImageScanSize },
): ImageScanBox {
  const scaleX = frame.width / image.width
  const scaleY = frame.height / image.height
  const scale = fit === "contain" ? Math.min(scaleX, scaleY) : Math.max(scaleX, scaleY)
  const width = image.width * scale
  const height = image.height * scale
  const left = (frame.width - width) / 2
  const top = (frame.height - height) / 2
  return { x: left + box.x * width, y: top + box.y * height, width: box.width * width, height: box.height * height }
}

/** A fraction from 0 to 1; anything else, or not a number, is pulled to the nearest end. */
const clampFraction = (value: number) => Math.min(1, Math.max(0, Number.isFinite(value) ? value : 0))

/** Keeps a box inside the image, so a detector's rounding never draws a box past its edge. */
function clampBox(box: ImageScanBox): ImageScanBox {
  const x = clampFraction(box.x)
  const y = clampFraction(box.y)
  return {
    x,
    y,
    width: Math.min(clampFraction(box.width), 1 - x),
    height: Math.min(clampFraction(box.height), 1 - y),
  }
}

export { clampBox, clampFraction, mapRegionBox }
export type { ImageScanBox, ImageScanFit, ImageScanSize }

"use client"

import type { ReactNode } from "react"
import { CheckIcon, CircleAlertIcon, RotateCcwIcon, ScanSearchIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import type { ImageScanStatus } from "@/components/ui/image-scan-primitive"
import { Progress, ProgressLabel, ProgressTrack, ProgressValue } from "@/components/ui/progress"
import { cn } from "@/lib/utils"

type ImageScanStep = { id: string; label: string }

type ImageScanLabels = {
  regions: string
  steps: string
  scan: string
  scanning: string
  cancel: string
  retry: string
  error: string
  found: (count: number) => string
  progress: (percent: number) => string
}

const imageScanLabels: ImageScanLabels = {
  regions: "Detected regions",
  steps: "Scan steps",
  scan: "Scan image",
  scanning: "Scanning image",
  cancel: "Cancel scan",
  retry: "Retry scan",
  error: "The scan failed",
  found: (count) => (count === 1 ? "1 item found" : `${String(count)} items found`),
  progress: (percent) => `Scan ${String(percent)}%`,
}

type ImageScanStatusBarProps = {
  status: ImageScanStatus
  progress?: number
  statusText?: string
  steps?: readonly ImageScanStep[]
  step?: string
  error?: string
  actions?: ReactNode
  count: number
  labels: ImageScanLabels
  scan?: (event: Event) => void
  cancel?: (event: Event) => void
  retry?: (event: Event) => void
}

/** What sits under the image in each state: the progress and Cancel, the error and Retry, or the count. */
function ImageScanStatusBar({
  status,
  progress,
  statusText,
  steps,
  step,
  count,
  error,
  labels,
  actions,
  scan,
  cancel,
  retry,
}: ImageScanStatusBarProps) {
  if (status === "scanning") {
    return (
      <div className="flex flex-col gap-items">
        <div className="flex items-end gap-items">
          <Progress value={progress === undefined ? null : Math.round(progress * 1000) / 10} className="min-w-0 flex-1">
            <ProgressLabel className="min-w-0 truncate">{statusText ?? labels.scanning}</ProgressLabel>
            <ProgressValue />
            <ProgressTrack />
          </Progress>
          {cancel ? (
            <Button variant="outline" size="sm" onClick={(event) => cancel(event.nativeEvent)}>
              <XIcon />
              {labels.cancel}
            </Button>
          ) : null}
          {actions}
        </div>
        {steps && steps.length > 0 ? <ImageScanSteps steps={steps} step={step} label={labels.steps} /> : null}
      </div>
    )
  }
  if (status === "error") {
    return (
      <div className="flex flex-wrap items-center gap-items">
        <p className="flex min-w-0 flex-1 basis-48 items-center gap-inline text-body-sm text-destructive-soft-foreground">
          <CircleAlertIcon aria-hidden className="size-4 shrink-0" />
          <span className="min-w-0">{error ?? labels.error}</span>
        </p>
        {retry ? (
          <Button variant="outline" size="sm" onClick={(event) => retry(event.nativeEvent)}>
            <RotateCcwIcon />
            {labels.retry}
          </Button>
        ) : null}
        {actions}
      </div>
    )
  }
  const summary = status === "result" ? labels.found(count) : null
  if (!summary && !scan && !actions) return null
  return (
    <div className="flex flex-wrap items-center gap-items">
      {summary ? <p className="min-w-0 flex-1 text-body-sm text-muted-foreground">{summary}</p> : null}
      {status === "uploaded" && scan ? (
        <Button size="sm" onClick={(event) => scan(event.nativeEvent)}>
          <ScanSearchIcon />
          {labels.scan}
        </Button>
      ) : null}
      {actions}
    </div>
  )
}

function ImageScanSteps({ steps, step, label }: { steps: readonly ImageScanStep[]; step?: string; label: string }) {
  const current = steps.findIndex((item) => item.id === step)
  return (
    <ol aria-label={label} className="flex flex-wrap gap-x-group gap-y-inline text-caption">
      {steps.map((item, index) => {
        const state = index < current ? "done" : index === current ? "current" : "pending"
        return (
          <li
            key={item.id}
            aria-current={state === "current" ? "step" : undefined}
            data-state={state}
            className="flex items-center gap-inline text-muted-foreground data-[state=current]:font-medium data-[state=current]:text-foreground"
          >
            {state === "done" ? (
              <CheckIcon aria-hidden strokeWidth={3} className="size-3 text-success" />
            ) : (
              <span
                aria-hidden
                className={cn(
                  "size-2 rounded-full border border-current",
                  state === "current" && "border-info bg-info",
                )}
              />
            )}
            {item.label}
          </li>
        )
      })}
    </ol>
  )
}

export { imageScanLabels, ImageScanStatusBar, ImageScanSteps }
export type { ImageScanLabels, ImageScanStatusBarProps, ImageScanStep }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createParts, usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { useMemo, type ComponentProps, type ReactNode } from "react"

import {
  clampBox,
  imageScan,
  mapRegionBox,
  type ImageScanActionReason,
  type ImageScanAnnouncements,
  type ImageScanBox,
  type ImageScanFit,
  type ImageScanSelectReason,
  type ImageScanStatus,
} from "@/components/ui/image-scan-primitive"
import {
  imageScanLabels,
  ImageScanStatusBar,
  type ImageScanLabels,
  type ImageScanStep,
} from "@/components/ui/image-scan-status"
import type { Tone } from "@/lib/tone"
import { cn, cnState } from "@/lib/utils"

const {
  Frame: ImageScanFrame,
  Image: ImageScanImage,
  Layer: ImageScanLayer,
  Effect: ImageScanEffect,
  Regions: ImageScanRegions,
  Region: ImageScanRegionButton,
  Legend: ImageScanLegend,
  LegendItem: ImageScanLegendItem,
} = createParts(imageScan, {
  frame: "div",
  image: "img",
  layer: "div",
  effect: "div",
  regions: "ol",
  region: "button",
  legend: "ul",
  "legend-item": "li",
})

/** Something the scan found, with its box on the image as fractions of the image's width and height. */
type ImageScanRegion = {
  id: string
  label: string
  box: ImageScanBox
  /** Extra text after the label, like a confidence: `"92%"`. */
  description?: string
  tone?: Tone
}

type ImageScanProps = Omit<PartProps<"div">, "children"> & {
  src: string
  /** Describes the image. Required: the scan is about what it shows. */
  alt: string
  /** The image's size in pixels, so the frame keeps its ratio before the image loads. */
  width?: number
  height?: number
  /** More props for the image element, like `srcSet`, `sizes` or `crossOrigin`. */
  imageProps?: Omit<ComponentProps<"img">, "src" | "alt" | "width" | "height">
  status?: ImageScanStatus
  /** From 0 to 1 while scanning; leave it out while the scan can't tell how far it is. */
  progress?: number
  /** What the scan is doing now, shown as the progress bar's label; `labels.scanning` by default. */
  statusText?: string
  steps?: readonly ImageScanStep[]
  /** The id of the step running now; the steps before it show as done. */
  step?: string
  regions?: readonly ImageScanRegion[]
  selectedRegion?: string | null
  defaultSelectedRegion?: string | null
  onSelectedRegionChange?: (region: string | null, details: ImageScanChangeDetails) => void
  /** Shows Cancel while scanning; agents call `cancel`. */
  onCancel?: (details: ImageScanEventDetails) => void
  /** Shows Retry after an error; agents call `retry`. */
  onRetry?: (details: ImageScanEventDetails) => void
  /** Shows a Scan button while the image waits; agents call `scan`. */
  onScan?: (details: ImageScanEventDetails) => void
  /** What went wrong, shown and read at once in the error state; `labels.error` by default. */
  error?: string
  /** How the image fills a frame of another ratio. Regions follow it. */
  fit?: ImageScanFit
  /** The frame's width over its height; the image's own by default, which leaves nothing to fit. */
  aspectRatio?: number
  /** Lists the regions under the image, linked to their boxes on hover. On by default. */
  legend?: boolean
  /** More controls beside the state's own, like a button to choose another image. */
  actions?: ReactNode
  labels?: Partial<ImageScanLabels>
}

type ImageScanEventDetails = ChangeDetails<ImageScanActionReason>
type ImageScanChangeDetails = ChangeDetails<ImageScanSelectReason>

// The image's drawn box: a frame of another ratio letterboxes it (contain) or crops it (cover), and regions are
// placed in fractions of this box, so they land on the pixels the image shows without measuring anything.
const layerClassName =
  // oxlint-disable-next-line shadcn/no-arbitrary-values -- the drawn image's size from the frame's container units and the image's ratio, for both fits
  "pointer-events-none absolute top-1/2 left-1/2 h-[min(100cqh,calc(100cqw/var(--image-scan-ratio)))] w-[min(100cqw,calc(100cqh*var(--image-scan-ratio)))] -translate-x-1/2 -translate-y-1/2 data-[fit=cover]:h-[max(100cqh,calc(100cqw/var(--image-scan-ratio)))] data-[fit=cover]:w-[max(100cqw,calc(100cqh*var(--image-scan-ratio)))]"

const regionColor =
  // oxlint-disable-next-line shadcn/no-arbitrary-values -- one colour per tone, read by the border, the fill and the legend's swatch
  "[--region-color:var(--primary)] data-[tone=neutral]:[--region-color:var(--muted-foreground)] data-[tone=info]:[--region-color:var(--info)] data-[tone=success]:[--region-color:var(--success)] data-[tone=warning]:[--region-color:var(--warning)] data-[tone=destructive]:[--region-color:var(--destructive)] data-[tone=violet]:[--region-color:var(--violet)]"

const regionClassName = cn(
  regionColor,
  // oxlint-disable-next-line shadcn/no-arbitrary-values -- a hairline of the background on both sides keeps the box visible on any photo; the stagger reads the region's index
  "group/region pointer-events-auto absolute cursor-pointer rounded-sm border-2 border-(--region-color) shadow-[0_0_0_1px_var(--background),inset_0_0_0_1px_var(--background)] outline-none transition delay-[calc(var(--image-scan-region-index)*60ms)] duration-panel ease-standard starting:scale-95 starting:opacity-0",
  "before:absolute before:inset-0 before:bg-(--region-color) before:opacity-0 before:transition-opacity before:duration-micro hover:before:opacity-20 data-highlighted:before:opacity-20 data-selected:border-3 data-selected:before:opacity-30",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
)

const chipClassName =
  "pointer-events-none absolute bottom-full left-0 flex max-w-48 items-center gap-inline truncate rounded-sm bg-popover px-inset-chip py-inset-chip text-caption font-medium whitespace-nowrap text-popover-foreground opacity-0 shadow-floating transition-opacity duration-micro group-hover/region:opacity-100 group-focus-visible/region:opacity-100 group-data-highlighted/region:opacity-100 group-data-selected/region:opacity-100 group-data-[align=end]/region:right-0 group-data-[align=end]/region:left-auto group-data-[edge=top]/region:top-0 group-data-[edge=top]/region:bottom-auto"

/* oxlint-disable shadcn/no-arbitrary-values -- the effect follows the progress and container variables, and draws a wedge and a halo no token describes */
const effectClassNames = {
  // The accent the sweep, the line and the brackets draw in: scanning is work in progress, the info tone's meaning.
  root: "group/effect absolute inset-0 overflow-hidden [--image-scan-accent:var(--info)]",
  // Dims the image, and once progress is known only the part still to scan: a scale, so nothing lays out.
  veil: "absolute inset-0 origin-bottom bg-overlay opacity-50 transition-transform duration-panel ease-standard group-data-determinate/effect:scale-y-[calc(1-var(--image-scan-progress,0))]",
  // While progress is unknown a wedge turns around the centre: one rotation on the compositor, gone under reduced
  // motion. 150cqmax covers the frame's diagonal from its centre.
  sweep:
    "absolute top-1/2 left-1/2 hidden size-[150cqmax] -translate-x-1/2 -translate-y-1/2 animate-spin rounded-full bg-[conic-gradient(from_0deg,transparent_0deg_250deg,color-mix(in_oklch,var(--image-scan-accent)_40%,transparent)_356deg,var(--image-scan-accent)_360deg)] [animation-duration:2.4s] group-not-data-determinate/effect:motion-safe:block",
  // With progress, a line that has scanned that far down: a translate of a box the height of the image.
  line: "absolute inset-x-0 bottom-full hidden h-full translate-y-[calc(var(--image-scan-progress,0)*100%)] border-b-2 border-(--image-scan-accent) bg-linear-to-b from-transparent to-(--image-scan-accent)/25 transition-transform duration-panel ease-standard group-data-determinate/effect:block",
  bracket:
    "absolute size-6 border-(--image-scan-accent) drop-shadow-[0_0_1px_var(--background)] motion-safe:animate-pulse",
}

// The frame is a size container (Tailwind's @container is inline-size only), so the layer and the sweep can size
// themselves from it in CSS.
const frameClassName =
  "relative aspect-(--image-scan-frame-ratio) w-full overflow-hidden rounded-surface border bg-muted [container-type:size]"
/* oxlint-enable shadcn/no-arbitrary-values */

const noRegions: readonly ImageScanRegion[] = []

function readingOrder(regions: readonly ImageScanRegion[]) {
  return regions.toSorted((a, b) => a.box.y - b.box.y || a.box.x - b.box.x)
}

/**
 * An image under analysis, from a controlled `status`: `uploaded` (a preview), `scanning` (a sweep over the image, a
 * progress bar and Cancel), `result` (the detected regions as buttons over the image and a legend) or `error` (the
 * message and Retry). Screen readers hear each change, progress at most every tenth, errors at once.
 */
function ImageScan({
  src,
  alt,
  width,
  height,
  imageProps,
  status = "uploaded",
  progress,
  statusText,
  steps,
  step,
  regions = noRegions,
  selectedRegion,
  defaultSelectedRegion,
  onSelectedRegionChange,
  onCancel,
  onRetry,
  onScan,
  error,
  fit = "contain",
  aspectRatio,
  legend = true,
  actions,
  labels: ownLabels,
  className,
  ...props
}: ImageScanProps) {
  const labels = { ...imageScanLabels, ...ownLabels }
  const ordered = useMemo(() => readingOrder(regions), [regions])
  const items = useMemo(() => ordered.map((region) => ({ value: region.id, label: region.label })), [ordered])
  const announcements: ImageScanAnnouncements = {
    scanning: statusText ?? labels.scanning,
    progress: labels.progress,
    result: labels.found,
    error: error ?? labels.error,
  }
  const scan = usePrimitive(imageScan, {
    status,
    progress,
    regions: items,
    selectedRegion,
    defaultSelectedRegion,
    onSelectedRegionChange,
    onCancel: onCancel && ((_value, details) => onCancel(details)),
    onRetry: onRetry && ((_value, details) => onRetry(details)),
    onScan: onScan && ((_value, details) => onScan(details)),
    ratio: width && height ? width / height : undefined,
    aspectRatio,
    fit,
    announcements,
  })

  const content = (
    <>
      <ImageScanFrame className={frameClassName}>
        <ImageScanImage
          {...imageProps}
          src={src}
          alt={alt}
          width={width}
          height={height}
          draggable={false}
          className={cnState(
            "absolute inset-0 size-full object-contain transition duration-panel ease-standard select-none data-[fit=cover]:object-cover data-[status=error]:opacity-60 data-[status=error]:grayscale",
            imageProps?.className,
          )}
        />
        <ImageScanLayer className={layerClassName}>
          <ImageScanEffect className={effectClassNames.root}>
            <span className={effectClassNames.veil} />
            <span className={effectClassNames.sweep} />
            <span className={effectClassNames.line} />
            <span
              className={cn(effectClassNames.bracket, "top-group left-group rounded-tl-sm border-t-2 border-l-2")}
            />
            <span
              className={cn(effectClassNames.bracket, "top-group right-group rounded-tr-sm border-t-2 border-r-2")}
            />
            <span
              className={cn(effectClassNames.bracket, "right-group bottom-group rounded-br-sm border-r-2 border-b-2")}
            />
            <span
              className={cn(effectClassNames.bracket, "bottom-group left-group rounded-bl-sm border-b-2 border-l-2")}
            />
          </ImageScanEffect>
          <ImageScanRegions label={labels.regions} className="absolute inset-0">
            {ordered.map((region, index) => (
              <li key={region.id} className="contents">
                <ImageScanRegionButton
                  value={region.id}
                  box={region.box}
                  tone={region.tone}
                  index={index}
                  className={regionClassName}
                >
                  <span className={chipClassName}>
                    <span className="truncate">{region.label}</span>
                    {region.description ? (
                      <>
                        {" "}
                        <span className="text-muted-foreground tabular-nums">{region.description}</span>
                      </>
                    ) : null}
                  </span>
                </ImageScanRegionButton>
              </li>
            ))}
          </ImageScanRegions>
        </ImageScanLayer>
      </ImageScanFrame>
      <ImageScanStatusBar
        status={status}
        progress={progress}
        statusText={statusText}
        steps={steps}
        step={step}
        count={regions.length}
        error={error}
        labels={labels}
        actions={actions}
        scan={onScan ? (event) => scan.api.scan(event) : undefined}
        cancel={onCancel ? (event) => scan.api.cancel(event) : undefined}
        retry={onRetry ? (event) => scan.api.retry(event) : undefined}
      />
      {legend ? (
        <ImageScanLegend className="flex flex-wrap gap-items">
          {ordered.map((region) => (
            <ImageScanLegendItem
              key={region.id}
              value={region.id}
              tone={region.tone}
              className={cn(
                regionColor,
                "flex min-w-0 cursor-pointer items-center gap-inline rounded-full border px-inset-chip py-inset-chip text-caption transition-colors duration-micro hover:bg-accent hover:text-accent-foreground data-highlighted:bg-accent data-highlighted:text-accent-foreground data-selected:border-(--region-color) data-selected:font-medium",
              )}
            >
              <span className="size-2 shrink-0 rounded-full bg-(--region-color)" />
              <span className="truncate">{region.label}</span>
              {region.description ? (
                <span className="text-muted-foreground tabular-nums">{region.description}</span>
              ) : null}
            </ImageScanLegendItem>
          ))}
        </ImageScanLegend>
      ) : null}
    </>
  )

  return usePart(
    scan,
    "root",
    {},
    {
      "aria-label": alt,
      ...props,
      className: cnState("flex w-full min-w-0 flex-col gap-items", className),
      children: content,
    },
    "div",
  )
}

